CREATE OR REPLACE FUNCTION public.fn_audit_log()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_row JSONB;
    v_old JSONB;
    v_new JSONB;
    v_id BIGINT;
    v_user_id INTEGER;
    v_pn INTEGER;
    v_project INTEGER;
    v_nucleo INTEGER;
    v_system_event_id TEXT;
BEGIN
    v_system_event_id := current_setting('app.auth_system_event_id', TRUE);
    IF TG_TABLE_NAME = 'sesion_usuario'
       AND TG_OP = 'UPDATE'
       AND NULLIF(v_system_event_id, '') IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM evento_acceso
            WHERE id_evento = v_system_event_id::BIGINT
              AND id_sesion = NEW.id_sesion
              AND id_usuario = NEW.id_usuario
              AND id_usuario_actor IS NULL
              AND tipo_evento = 'sesion_expirada'
              AND motivo_codigo = NEW.motivo_revocacion
              AND motivo_codigo IN ('expiracion_inactividad', 'expiracion_absoluta')
              AND txid_registro = txid_current()
        ) OR OLD.revocada_en IS NOT NULL
          OR NEW.revocada_en IS NULL
          OR NEW.id_usuario_revoca IS NOT NULL
          OR to_jsonb(NEW) - ARRAY['revocada_en','id_usuario_revoca','motivo_revocacion']
             IS DISTINCT FROM
             to_jsonb(OLD) - ARRAY['revocada_en','id_usuario_revoca','motivo_revocacion'] THEN
            RAISE EXCEPTION 'Expiración de sesión sin evento de sistema correlacionado o con cambios no permitidos';
        END IF;
        RETURN NEW;
    END IF;

    IF TG_OP = 'INSERT' THEN
        v_new := to_jsonb(NEW) - ARRAY['contrasena_hash', 'token_hash', 'csrf_hash'];
        v_row := v_new;
    ELSIF TG_OP = 'UPDATE' THEN
        -- This check deliberately precedes the secret-only no-op return.
        v_user_id := NULLIF(current_setting('app.current_user_id', TRUE), '')::INTEGER;
        IF v_user_id IS NULL THEN
            RAISE EXCEPTION 'Auditoría fallida: falta app.current_user_id en la transacción';
        END IF;
        v_old := to_jsonb(OLD) - ARRAY['contrasena_hash', 'token_hash', 'csrf_hash'];
        v_new := to_jsonb(NEW) - ARRAY['contrasena_hash', 'token_hash', 'csrf_hash'];
        IF v_old IS NOT DISTINCT FROM v_new THEN
            RETURN NEW;
        END IF;
        v_row := v_new;
    ELSE
        v_old := to_jsonb(OLD) - ARRAY['contrasena_hash', 'token_hash', 'csrf_hash'];
        v_row := v_old;
    END IF;

    IF TG_OP <> 'UPDATE' THEN
        v_user_id := NULLIF(current_setting('app.current_user_id', TRUE), '')::INTEGER;
        IF v_user_id IS NULL THEN
            RAISE EXCEPTION 'Auditoría fallida: falta app.current_user_id en la transacción';
        END IF;
    END IF;
    v_id := NULLIF(v_row ->> TG_ARGV[0], '')::BIGINT;
    v_pn := NULLIF(v_row ->> 'id_proyecto_nucleo', '')::INTEGER;
    v_project := NULLIF(v_row ->> 'id_proyecto', '')::INTEGER;
    v_nucleo := NULLIF(v_row ->> 'id_nucleo', '')::INTEGER;

    IF TG_TABLE_NAME = 'proyecto' THEN v_project := v_id::INTEGER; END IF;
    IF TG_TABLE_NAME = 'proyecto_nucleo' THEN v_pn := v_id::INTEGER; END IF;
    IF TG_TABLE_NAME = 'nucleo_agrario' THEN v_nucleo := v_id::INTEGER; END IF;

    IF v_pn IS NULL AND TG_TABLE_NAME IN ('convenio_afectacion', 'indemnizacion', 'pago') THEN
        IF TG_TABLE_NAME = 'convenio_afectacion' THEN
            SELECT c.id_proyecto_nucleo INTO v_pn FROM convenio c WHERE c.id_convenio = (v_row ->> 'id_convenio')::INTEGER;
        ELSIF TG_TABLE_NAME = 'indemnizacion' THEN
            SELECT a.id_proyecto_nucleo INTO v_pn FROM afectacion a WHERE a.id_afectacion = (v_row ->> 'id_afectacion')::INTEGER;
        ELSE
            SELECT a.id_proyecto_nucleo INTO v_pn
            FROM indemnizacion i JOIN afectacion a ON a.id_afectacion = i.id_afectacion
            WHERE i.id_indemnizacion = (v_row ->> 'id_indemnizacion')::INTEGER;
        END IF;
    END IF;
    IF v_pn IS NOT NULL THEN
        SELECT pn.id_proyecto, pn.id_nucleo INTO v_project, v_nucleo
        FROM proyecto_nucleo pn WHERE pn.id_proyecto_nucleo = v_pn;
    END IF;

    INSERT INTO bitacora (
        id_usuario, id_proyecto, id_proyecto_nucleo, id_nucleo,
        entidad_tipo, entidad_id, accion, valor_anterior, valor_nuevo
    ) VALUES (
        v_user_id, v_project, v_pn, v_nucleo,
        TG_TABLE_NAME, v_id, lower(TG_OP), v_old, v_new
    );
    RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_auth_revocar_sesiones_usuario_inactivo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_actor TEXT;
    v_sesion RECORD;
BEGIN
    IF OLD.activo = TRUE AND NEW.activo = FALSE THEN
        v_actor := current_setting('app.current_user_id', true);
        IF v_actor IS NULL OR v_actor = '' THEN
            RAISE EXCEPTION
                'La baja de usuario requiere actor para revocar sesiones';
        END IF;
        FOR v_sesion IN
            UPDATE sesion_usuario
               SET revocada_en = NOW(),
                   id_usuario_revoca = v_actor::INTEGER,
                   motivo_revocacion = 'usuario_inactivo'
             WHERE id_usuario = NEW.id_usuario
               AND revocada_en IS NULL
            RETURNING id_sesion
        LOOP
            INSERT INTO evento_acceso (
                id_usuario, id_usuario_actor, id_sesion,
                tipo_evento, motivo_codigo
            ) VALUES (
                NEW.id_usuario, v_actor::INTEGER, v_sesion.id_sesion,
                'sesion_revocada', 'usuario_inactivo'
            );
        END LOOP;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_auth_validar_estado_evento()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_event_id TEXT;
BEGIN
    v_event_id := current_setting('app.auth_event_id', true);
    IF v_event_id IS NULL OR v_event_id = '' OR NOT EXISTS (
        SELECT 1
          FROM evento_acceso
         WHERE id_evento = v_event_id::BIGINT
           AND id_usuario = NEW.id_usuario
           AND txid_registro = txid_current()
    ) THEN
        RAISE EXCEPTION
            'Estado de autenticacion sin evento correlacionado en la transaccion';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_catalogo_inmutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Los catálogos no admiten DELETE físico; desactive la opción';
    END IF;
    IF NEW.tipo_catalogo IS DISTINCT FROM OLD.tipo_catalogo
       OR NEW.codigo IS DISTINCT FROM OLD.codigo THEN
        RAISE EXCEPTION 'El tipo y código estable de catálogo son inmutables';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_compareciente_identidad_inmutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.id_convenio IS DISTINCT FROM NEW.id_convenio
       OR OLD.id_persona IS DISTINCT FROM NEW.id_persona
       OR OLD.id_parcela_titular IS DISTINCT FROM NEW.id_parcela_titular THEN
        RAISE EXCEPTION '039: identidad del compareciente inmutable; cree un nuevo registro y de baja logica al anterior';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_convenio_requiere_afectacion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id INTEGER := CASE WHEN TG_TABLE_NAME = 'convenio' THEN NEW.id_convenio ELSE NEW.id_convenio END;
BEGIN
    IF EXISTS (SELECT 1 FROM convenio WHERE id_convenio = v_id AND activo)
       AND NOT EXISTS (SELECT 1 FROM convenio_afectacion WHERE id_convenio = v_id AND activo) THEN
        RAISE EXCEPTION 'Un convenio activo requiere al menos una afectación activa asociada';
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fifonafe_requiere_afectacion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id INTEGER := NEW.id_tramite_fifonafe;
BEGIN
    IF EXISTS (SELECT 1 FROM tramite_fifonafe WHERE id_tramite_fifonafe = v_id AND activo)
       AND NOT EXISTS (SELECT 1 FROM tramite_fifonafe_afectacion WHERE id_tramite_fifonafe = v_id AND activo) THEN
        RAISE EXCEPTION 'Un trámite FIFONAFE activo requiere al menos una afectación activa asociada';
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_gis_feature_confirmada_inmutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 BEGIN
 IF OLD.estado='confirmado' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
  RAISE EXCEPTION 'Feature GIS confirmada inmutable; utilizar nueva importacion';
 END IF;
 RETURN NEW;
 END $function$

CREATE OR REPLACE FUNCTION public.fn_gis_validar_candidato()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 DECLARE v_proyecto integer; v_objetivo text; v_version text;
 BEGIN
 SELECT id_proyecto,tipo_objetivo,version_pipeline INTO v_proyecto,v_objetivo,v_version
 FROM importacion_archivo WHERE id_importacion=NEW.id_importacion AND activo;
 IF v_proyecto IS NULL OR v_version='legacy-v1' OR NOT EXISTS(
 SELECT 1 FROM proyecto_nucleo pn JOIN nucleo_agrario n USING(id_nucleo) JOIN proyecto pr USING(id_proyecto)
 WHERE pn.id_proyecto_nucleo=NEW.id_proyecto_nucleo AND pn.id_proyecto=v_proyecto AND pn.activo AND n.activo AND pr.activo)
 THEN RAISE EXCEPTION 'Candidato fuera del universo administrativo del proyecto'; END IF;
 IF v_objetivo IN('parcela','parcela_gpkg') THEN
  IF NEW.id_parcela IS NULL OR NOT EXISTS(SELECT 1 FROM vw_gis_parcela_proyecto
   WHERE id_proyecto_nucleo=NEW.id_proyecto_nucleo AND id_parcela=NEW.id_parcela AND id_proyecto=v_proyecto)
  THEN RAISE EXCEPTION 'Parcela sin vinculo administrativo activo con el proyecto'; END IF;
 ELSIF v_objetivo IN('nucleo_agrario','nucleo_agrario_gpkg') THEN
  IF NEW.id_parcela IS NOT NULL THEN RAISE EXCEPTION 'Destino no corresponde a nucleo'; END IF;
 ELSE RAISE EXCEPTION 'Objetivo no conciliable'; END IF;
 IF NEW.estado IN('seleccionado','confirmado') AND NOT EXISTS(SELECT 1 FROM usuario
 WHERE id_usuario=NULLIF(current_setting('app.current_user_id',true),'')::integer AND activo AND rol IN('admin','geografo'))
 THEN RAISE EXCEPTION 'Decision GIS requiere admin o geografo'; END IF;
 IF TG_OP='UPDATE' AND OLD.estado='confirmado' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD)
 THEN RAISE EXCEPTION 'Candidato confirmado inmutable'; END IF;
 RETURN NEW;
 END $function$

CREATE OR REPLACE FUNCTION public.fn_gis_validar_geometria_contexto()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
 DECLARE v_feature importacion_feature%ROWTYPE; v_import importacion_archivo%ROWTYPE;
 BEGIN
 SELECT * INTO v_feature FROM importacion_feature WHERE id_importacion_feature=NEW.id_importacion_feature;
 SELECT * INTO v_import FROM importacion_archivo WHERE id_importacion=v_feature.id_importacion;
 IF v_feature.estado_conciliacion<>'confirmado' OR NOT EXISTS(
 SELECT 1 FROM importacion_feature_candidato c JOIN proyecto_nucleo pn USING(id_proyecto_nucleo)
 WHERE c.id_importacion_feature=NEW.id_importacion_feature AND c.estado='confirmado'
 AND c.id_proyecto_nucleo=NEW.id_proyecto_nucleo AND pn.id_proyecto=v_import.id_proyecto
 AND ((TG_TABLE_NAME='proyecto_nucleo_geometria' AND c.id_parcela IS NULL)
 OR (TG_TABLE_NAME='proyecto_parcela_geometria' AND c.id_parcela=(to_jsonb(NEW)->>'id_parcela')::integer)))
 THEN RAISE EXCEPTION 'Geometria sin destino confirmado del mismo proyecto'; END IF;
 IF NEW.srid_trabajo<>v_import.srid_trabajo OR NEW.geometria_poligono IS DISTINCT FROM v_feature.geometria_normalizada
 OR NEW.geometria_trabajo IS DISTINCT FROM v_feature.geometria_trabajo
 THEN RAISE EXCEPTION 'Geometria o CRS distintos del staging confirmado'; END IF;
 RETURN NEW;
 END $function$

CREATE OR REPLACE FUNCTION public.fn_objetivo_requisito_en_pn(p_tipo text, p_id bigint, p_pn integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
 CASE p_tipo
 WHEN 'orv' THEN RETURN EXISTS(SELECT 1 FROM orv o JOIN proyecto_nucleo pn ON pn.id_nucleo=o.id_nucleo WHERE o.id_orv=p_id AND pn.id_proyecto_nucleo=p_pn AND o.activo AND pn.activo);
 WHEN 'padron_historial' THEN RETURN EXISTS(SELECT 1 FROM padron_historial ph JOIN proyecto_nucleo pn ON pn.id_nucleo=ph.id_nucleo WHERE ph.id_padron=p_id AND pn.id_proyecto_nucleo=p_pn AND ph.activo AND pn.activo);
 WHEN 'actividad_campo' THEN RETURN EXISTS(SELECT 1 FROM actividad_campo a WHERE a.id_actividad=p_id AND a.id_proyecto_nucleo=p_pn AND a.activo);
 WHEN 'asamblea' THEN RETURN EXISTS(SELECT 1 FROM asamblea a WHERE a.id_asamblea=p_id AND a.id_proyecto_nucleo=p_pn AND a.activo);
 WHEN 'asamblea_convocatoria' THEN RETURN EXISTS(SELECT 1 FROM asamblea_convocatoria ac JOIN asamblea a USING(id_asamblea) WHERE ac.id_convocatoria=p_id AND a.id_proyecto_nucleo=p_pn AND ac.activo AND a.activo);
 WHEN 'tramite_fifonafe_interviniente' THEN RETURN EXISTS(SELECT 1 FROM tramite_fifonafe_interviniente i JOIN tramite_fifonafe t USING(id_tramite_fifonafe) WHERE i.id_interviniente_fifonafe=p_id AND t.id_proyecto_nucleo=p_pn AND i.activo AND t.activo);
 ELSE RETURN public.fn_objetivo_requisito_en_pn_001(p_tipo,p_id,p_pn);
 END CASE;
END $function$

CREATE OR REPLACE FUNCTION public.fn_objetivo_requisito_en_pn_001(p_tipo text, p_id bigint, p_pn integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_ok BOOLEAN := FALSE;
BEGIN
    CASE p_tipo
        WHEN 'proyecto_nucleo' THEN
            SELECT EXISTS(
                SELECT 1 FROM proyecto_nucleo pn
                 WHERE pn.id_proyecto_nucleo=p_id AND pn.id_proyecto_nucleo=p_pn AND pn.activo
            ) INTO v_ok;
        WHEN 'afectacion' THEN
            SELECT EXISTS(
                SELECT 1 FROM afectacion a
                 WHERE a.id_afectacion=p_id AND a.id_proyecto_nucleo=p_pn AND a.activo
            ) INTO v_ok;
        WHEN 'parcela' THEN
            SELECT EXISTS(
                SELECT 1 FROM parcela p
                JOIN proyecto_nucleo pn ON pn.id_nucleo=p.id_nucleo
                 WHERE p.id_parcela=p_id AND pn.id_proyecto_nucleo=p_pn AND p.activo AND pn.activo
            ) INTO v_ok;
        WHEN 'parcela_titular' THEN
            SELECT EXISTS(
                SELECT 1 FROM parcela_titular pt
                JOIN parcela p ON p.id_parcela=pt.id_parcela
                JOIN proyecto_nucleo pn ON pn.id_nucleo=p.id_nucleo
                 WHERE pt.id_parcela_titular=p_id AND pn.id_proyecto_nucleo=p_pn
                   AND pt.activo AND p.activo AND pn.activo
            ) INTO v_ok;
        WHEN 'unidad_agraria' THEN
            SELECT EXISTS(
                SELECT 1 FROM unidad_agraria u
                JOIN proyecto_nucleo pn ON pn.id_nucleo=u.id_nucleo
                 WHERE u.id_unidad_agraria=p_id AND pn.id_proyecto_nucleo=p_pn
                   AND u.activo AND pn.activo
            ) INTO v_ok;
        WHEN 'unidad_agraria_titular' THEN
            SELECT EXISTS(
                SELECT 1 FROM unidad_agraria_titular ut
                JOIN unidad_agraria u ON u.id_unidad_agraria=ut.id_unidad_agraria
                JOIN proyecto_nucleo pn ON pn.id_nucleo=u.id_nucleo
                 WHERE ut.id_unidad_titular=p_id AND pn.id_proyecto_nucleo=p_pn
                   AND ut.activo AND u.activo AND pn.activo
            ) INTO v_ok;
        WHEN 'convenio' THEN
            SELECT EXISTS(
                SELECT 1 FROM convenio c
                 WHERE c.id_convenio=p_id AND c.id_proyecto_nucleo=p_pn AND c.activo
            ) INTO v_ok;
        WHEN 'convenio_compareciente' THEN
            SELECT EXISTS(
                SELECT 1 FROM convenio_compareciente cc
                JOIN convenio c ON c.id_convenio=cc.id_convenio
                 WHERE cc.id_compareciente=p_id AND c.id_proyecto_nucleo=p_pn
                   AND cc.activo AND c.activo
            ) INTO v_ok;
        WHEN 'tramite_ran' THEN
            SELECT EXISTS(
                SELECT 1 FROM tramite_ran t
                 WHERE t.id_tramite_ran=p_id AND t.id_proyecto_nucleo=p_pn AND t.activo
            ) INTO v_ok;
        WHEN 'tramite_ran_evento' THEN
            SELECT EXISTS(
                SELECT 1 FROM tramite_ran_evento e
                JOIN tramite_ran t ON t.id_tramite_ran=e.id_tramite_ran
                 WHERE e.id_evento_ran=p_id AND t.id_proyecto_nucleo=p_pn
                   AND e.activo AND t.activo
            ) INTO v_ok;
        WHEN 'tramite_fifonafe' THEN
            SELECT EXISTS(
                SELECT 1 FROM tramite_fifonafe t
                 WHERE t.id_tramite_fifonafe=p_id AND t.id_proyecto_nucleo=p_pn AND t.activo
            ) INTO v_ok;
        WHEN 'tramite_fifonafe_evento' THEN
            SELECT EXISTS(
                SELECT 1 FROM tramite_fifonafe_evento e
                JOIN tramite_fifonafe t ON t.id_tramite_fifonafe=e.id_tramite_fifonafe
                 WHERE e.id_evento_fifonafe=p_id AND t.id_proyecto_nucleo=p_pn
                   AND e.activo AND t.activo
            ) INTO v_ok;
        WHEN 'indemnizacion' THEN
            SELECT EXISTS(
                SELECT 1 FROM indemnizacion i
                JOIN afectacion a ON a.id_afectacion=i.id_afectacion
                 WHERE i.id_indemnizacion=p_id AND a.id_proyecto_nucleo=p_pn
                   AND i.activo AND a.activo
            ) INTO v_ok;
        WHEN 'pago' THEN
            SELECT EXISTS(
                SELECT 1 FROM pago pg
                JOIN indemnizacion i ON i.id_indemnizacion=pg.id_indemnizacion
                JOIN afectacion a ON a.id_afectacion=i.id_afectacion
                 WHERE pg.id_pago=p_id AND a.id_proyecto_nucleo=p_pn
                   AND pg.activo AND i.activo AND a.activo
            ) INTO v_ok;
        ELSE
            v_ok := FALSE;
    END CASE;
    RETURN COALESCE(v_ok,FALSE);
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_proteger_baja_persona()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.activo AND NOT NEW.activo THEN
        PERFORM pg_advisory_xact_lock(
            hashtextextended('software-pa:persona-relaciones:' || NEW.id_persona, 0)
        );
        IF fn_persona_tiene_relaciones_activas(NEW.id_persona) THEN
            RAISE EXCEPTION
                'La persona mantiene relaciones activas y no puede darse de baja';
        END IF;
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_actividad_afectacion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_pn INTEGER;
BEGIN
    IF NEW.id_afectacion IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT id_proyecto_nucleo
      INTO v_pn
      FROM afectacion
     WHERE id_afectacion = NEW.id_afectacion
       AND activo;

    IF v_pn IS NULL THEN
        RAISE EXCEPTION '039: la afectacion de la actividad no existe o esta inactiva';
    END IF;
    IF v_pn IS DISTINCT FROM NEW.id_proyecto_nucleo THEN
        RAISE EXCEPTION '039: actividad y afectacion deben pertenecer al mismo ProyectoNucleo';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_administrador_activo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.activo AND OLD.rol = 'admin'
       AND (NEW.activo IS FALSE OR NEW.rol <> 'admin') THEN
        PERFORM pg_advisory_xact_lock(hashtext('software_pa_active_admin'));
        IF NOT EXISTS (
            SELECT 1 FROM usuario
             WHERE activo AND rol = 'admin' AND id_usuario <> OLD.id_usuario
        ) THEN
            RAISE EXCEPTION 'ADM_ULTIMO_ADMIN_ACTIVO';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_afectacion_tipo_cop()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_cop_operativo,'tipo_cop_operativo') THEN
        RAISE EXCEPTION 'TIPO COP operativo invalido';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_afectacion_unidad()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_nucleo_afectacion INTEGER;
    v_nucleo_unidad INTEGER;
    v_tipo_afectacion TEXT;
    v_parcela_unidad INTEGER;
BEGIN
    SELECT pn.id_nucleo, a.tipo_afectacion
      INTO v_nucleo_afectacion, v_tipo_afectacion
      FROM afectacion a
      JOIN proyecto_nucleo pn ON pn.id_proyecto_nucleo=a.id_proyecto_nucleo
     WHERE a.id_afectacion=NEW.id_afectacion AND a.activo AND pn.activo;

    SELECT id_nucleo, id_parcela
      INTO v_nucleo_unidad, v_parcela_unidad
      FROM unidad_agraria
     WHERE id_unidad_agraria=NEW.id_unidad_agraria AND activo;

    IF v_nucleo_afectacion IS NULL OR v_nucleo_unidad IS NULL
       OR v_nucleo_afectacion<>v_nucleo_unidad THEN
        RAISE EXCEPTION 'Afectacion y unidad agraria deben pertenecer al mismo nucleo';
    END IF;
    IF v_tipo_afectacion='individual' AND v_parcela_unidad IS NULL THEN
        RAISE EXCEPTION 'La unidad de una afectacion individual debe referenciar una parcela';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_alias_territorial_objetivo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_entidad INTEGER;
BEGIN
    SELECT id_entidad INTO v_entidad FROM municipio WHERE id_municipio = NEW.id_municipio_destino AND activo;
    IF v_entidad IS NULL OR v_entidad <> NEW.id_entidad THEN
        RAISE EXCEPTION 'El municipio destino del alias no pertenece a la entidad indicada';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_asamblea_catalogos()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_tipo text; v_contexto text;
BEGIN
 IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_asamblea,'tipo_asamblea')
    OR (NEW.id_contexto_asamblea IS NOT NULL AND NOT fn_opcion_catalogo_valida(NEW.id_contexto_asamblea,'contexto_asamblea'))
    OR (NEW.id_tipo_cop_operativo IS NOT NULL AND NOT fn_opcion_catalogo_valida(NEW.id_tipo_cop_operativo,'tipo_cop_operativo')) THEN
   RAISE EXCEPTION 'Tipo, contexto o tipo COP de asamblea invalido';
 END IF;
 SELECT codigo INTO v_tipo FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_tipo_asamblea;
 SELECT codigo INTO v_contexto FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_contexto_asamblea;
 IF (v_tipo='retiro_fondos' AND v_contexto IS DISTINCT FROM 'retiro_fondos') OR (v_tipo='anuencia' AND v_contexto='retiro_fondos') THEN RAISE EXCEPTION 'Tipo de asamblea y contexto contradictorios'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_asamblea_convocatoria()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_resultado TEXT;
BEGIN
    IF NEW.id_resultado IS NOT NULL THEN
        SELECT codigo INTO v_resultado
          FROM catalogo_operativo
         WHERE id_catalogo_opcion=NEW.id_resultado
           AND tipo_catalogo='resultado_convocatoria';
        IF v_resultado IS NULL THEN
            RAISE EXCEPTION 'Resultado de convocatoria invalido';
        END IF;
    END IF;

    IF NEW.fecha_realizacion IS NOT NULL AND v_resultado IS DISTINCT FROM 'celebrada' THEN
        RAISE EXCEPTION 'fecha_realizacion requiere resultado celebrada';
    END IF;
    IF v_resultado='celebrada' AND NEW.fecha_realizacion IS NULL THEN
        RAISE EXCEPTION 'Una convocatoria celebrada requiere fecha_realizacion';
    END IF;

    IF NEW.activo AND v_resultado='celebrada' THEN
        PERFORM 1 FROM asamblea WHERE id_asamblea=NEW.id_asamblea FOR UPDATE;
        IF EXISTS (
            SELECT 1
              FROM asamblea_convocatoria ac
              JOIN catalogo_operativo co ON co.id_catalogo_opcion=ac.id_resultado
             WHERE ac.id_asamblea=NEW.id_asamblea
               AND ac.activo
               AND co.tipo_catalogo='resultado_convocatoria'
               AND co.codigo='celebrada'
               AND ac.id_convocatoria IS DISTINCT FROM NEW.id_convocatoria
        ) THEN
            RAISE EXCEPTION 'Una asamblea solo puede tener una convocatoria celebrada activa';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_asamblea_padron()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_nucleo_pn INTEGER;
    v_nucleo_padron INTEGER;
BEGIN
    IF NEW.id_padron IS NOT NULL AND NEW.activo THEN
        SELECT id_nucleo INTO v_nucleo_pn FROM proyecto_nucleo
        WHERE id_proyecto_nucleo = NEW.id_proyecto_nucleo AND activo;
        SELECT id_nucleo INTO v_nucleo_padron FROM padron_historial
        WHERE id_padron = NEW.id_padron AND activo;
        IF v_nucleo_pn IS NULL OR v_nucleo_padron IS NULL OR v_nucleo_pn <> v_nucleo_padron THEN
            RAISE EXCEPTION 'El padrón de la asamblea debe pertenecer al mismo núcleo';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_catalogos_dominio()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_organo TEXT;
    v_cargo TEXT;
BEGIN
    IF TG_TABLE_NAME='nucleo_agrario' THEN
        IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_tenencia,'tipo_tenencia') THEN
            RAISE EXCEPTION 'Tipo de tenencia invalido';
        END IF;
    ELSIF TG_TABLE_NAME='proyecto_nucleo' THEN
        IF NEW.id_residencia IS NOT NULL
           AND NOT fn_opcion_catalogo_valida(NEW.id_residencia,'residencia') THEN
            RAISE EXCEPTION 'Residencia invalida';
        END IF;
    ELSIF TG_TABLE_NAME='orv' THEN
        IF NEW.id_estado_registral IS NOT NULL
           AND NOT fn_opcion_catalogo_valida(NEW.id_estado_registral,'estado_registral_orv') THEN
            RAISE EXCEPTION 'Estado registral ORV invalido';
        END IF;
    ELSIF TG_TABLE_NAME='orv_integrante' THEN
        IF NOT fn_opcion_catalogo_valida(NEW.id_organo,'organo_orv')
           OR NOT fn_opcion_catalogo_valida(NEW.id_cargo,'cargo_orv')
           OR NOT fn_opcion_catalogo_valida(NEW.id_calidad,'calidad_integrante_orv') THEN
            RAISE EXCEPTION 'Estructura ORV invalida';
        END IF;
        SELECT codigo INTO v_organo FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_organo;
        SELECT codigo INTO v_cargo FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_cargo;
        IF (v_organo='comisariado' AND v_cargo NOT IN ('presidente','secretario','tesorero'))
           OR (v_organo='consejo_vigilancia' AND v_cargo NOT IN ('presidente','secretario_1','secretario_2')) THEN
            RAISE EXCEPTION 'Cargo % no pertenece al organo %',v_cargo,v_organo;
        END IF;
    ELSIF TG_TABLE_NAME='tramite_ran_evento' THEN
        IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_evento,'tipo_evento_ran') THEN
            RAISE EXCEPTION 'Tipo de evento RAN invalido';
        END IF;
    ELSIF TG_TABLE_NAME='tramite_fifonafe_evento' THEN
        IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_evento,'tipo_evento_fifonafe') THEN
            RAISE EXCEPTION 'Tipo de evento FIFONAFE invalido';
        END IF;
    ELSIF TG_TABLE_NAME='expediente_requisito' THEN
        IF NOT fn_opcion_catalogo_valida(NEW.id_estado,'estado_requisito_documental') THEN
            RAISE EXCEPTION 'Estado de requisito documental invalido';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_compareciente()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_ambito varchar(20); v_pn integer; v_nucleo integer; v_persona_titular integer;
    v_nucleo_parcela integer; v_titular_inicio date; v_titular_fin date;
    v_fecha_firma date; v_orv_vigente boolean := false;
    v_acreditacion_historica boolean := false; v_documento_acreditacion boolean := false;
BEGIN
    IF NOT NEW.activo THEN RETURN NEW; END IF;
    SELECT c.ambito,c.id_proyecto_nucleo,pn.id_nucleo,c.fecha_firma
      INTO v_ambito,v_pn,v_nucleo,v_fecha_firma
      FROM convenio c JOIN proyecto_nucleo pn ON pn.id_proyecto_nucleo=c.id_proyecto_nucleo
     WHERE c.id_convenio=NEW.id_convenio AND c.activo AND pn.activo;
    IF v_pn IS NULL THEN RAISE EXCEPTION '007: convenio del compareciente inexistente o inactivo'; END IF;
    IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_calidad,'calidad_compareciente_convenio') THEN
        RAISE EXCEPTION '007: calidad de compareciente invalida';
    END IF;

    IF v_ambito='individual' THEN
        IF NEW.id_tipo_acreditacion IS NOT NULL
           AND NOT fn_opcion_catalogo_valida(NEW.id_tipo_acreditacion,'tipo_acreditacion_derecho_individual') THEN
            RAISE EXCEPTION '039: tipo de acreditacion individual invalido';
        END IF;
        IF NEW.id_parcela_titular IS NOT NULL THEN
            SELECT pt.id_persona,p.id_nucleo,pt.fecha_inicio,pt.fecha_fin
              INTO v_persona_titular,v_nucleo_parcela,v_titular_inicio,v_titular_fin
              FROM parcela_titular pt JOIN parcela p ON p.id_parcela=pt.id_parcela
             WHERE pt.id_parcela_titular=NEW.id_parcela_titular AND pt.activo AND p.activo;
            IF v_persona_titular IS NULL THEN RAISE EXCEPTION '039: ParcelaTitular del compareciente inexistente o inactivo'; END IF;
            IF v_persona_titular IS DISTINCT FROM NEW.id_persona THEN RAISE EXCEPTION '039: ParcelaTitular no pertenece a la persona compareciente'; END IF;
            IF v_nucleo_parcela IS DISTINCT FROM v_nucleo THEN RAISE EXCEPTION '039: la parcela del compareciente no pertenece al NucleoAgrario del ProyectoNucleo'; END IF;
            IF v_fecha_firma IS NOT NULL AND v_titular_inicio IS NOT NULL AND v_fecha_firma<v_titular_inicio THEN RAISE EXCEPTION '039: la titularidad inicia despues de la fecha de firma del convenio'; END IF;
            IF v_fecha_firma IS NOT NULL AND v_titular_fin IS NOT NULL AND v_fecha_firma>v_titular_fin THEN RAISE EXCEPTION '039: la titularidad termino antes de la fecha de firma del convenio'; END IF;
        END IF;
        IF NEW.es_firmante AND NEW.id_parcela_titular IS NULL AND NEW.id_tipo_acreditacion IS NULL THEN
            RAISE EXCEPTION '039: firmante individual requiere ParcelaTitular o acreditacion alternativa';
        END IF;
    ELSIF v_ambito='colectivo' THEN
        IF NEW.id_parcela_titular IS NOT NULL THEN
            RAISE EXCEPTION '007: compareciente colectivo no usa ParcelaTitular';
        END IF;
        IF NEW.id_tipo_acreditacion IS NOT NULL
           AND NOT fn_opcion_catalogo_valida(NEW.id_tipo_acreditacion,'tipo_acreditacion_compareciente_colectivo') THEN
            RAISE EXCEPTION '007: tipo de acreditacion colectiva invalido';
        END IF;
        IF v_fecha_firma IS NOT NULL THEN
            SELECT EXISTS (
                SELECT 1 FROM orv_integrante oi JOIN orv o ON o.id_orv=oi.id_orv
                WHERE oi.id_persona=NEW.id_persona AND oi.activo AND o.activo
                  AND o.id_nucleo=v_nucleo
                  AND (oi.fecha_inicio IS NULL OR oi.fecha_inicio<=v_fecha_firma)
                  AND (oi.fecha_fin IS NULL OR oi.fecha_fin>=v_fecha_firma)
                  AND (o.inicio_vigencia IS NULL OR o.inicio_vigencia<=v_fecha_firma)
                  AND (o.fin_vigencia IS NULL OR o.fin_vigencia>=v_fecha_firma)
            ) INTO v_orv_vigente;
        END IF;
        v_acreditacion_historica := NEW.id_tipo_acreditacion IS NOT NULL
            AND NULLIF(btrim(NEW.referencia_acreditacion),'') IS NOT NULL
            AND NEW.fecha_acreditacion IS NOT NULL
            AND v_fecha_firma IS NOT NULL
            AND NEW.fecha_acreditacion<=v_fecha_firma;
        SELECT EXISTS (
            SELECT 1 FROM documento_vinculo dv
            JOIN documento d ON d.id_documento=dv.id_documento
            WHERE dv.activo AND d.activo AND d.estado='disponible'
              AND dv.entidad_tipo='convenio_compareciente'
              AND dv.entidad_id=NEW.id_compareciente
        ) INTO v_documento_acreditacion;
        IF NEW.es_firmante AND NOT v_orv_vigente
           AND NOT (v_acreditacion_historica AND v_documento_acreditacion)
           AND NOT NEW.requiere_revision THEN
            RAISE EXCEPTION '007: firmante colectivo requiere ORV vigente al acto, acreditacion externa documentada o revision explicita';
        END IF;
    ELSE
        RAISE EXCEPTION '007: ambito de convenio invalido';
    END IF;

    IF NEW.es_firmante AND NEW.id_parcela_titular IS NULL
       AND NEW.id_tipo_acreditacion IS NOT NULL
       AND NULLIF(btrim(NEW.referencia_acreditacion),'') IS NULL
       AND NOT NEW.requiere_revision THEN
        RAISE EXCEPTION '007: acreditacion sin referencia debe quedar explicitamente en revision';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_convenio_afectacion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_convenio convenio%ROWTYPE;
    v_afectacion afectacion%ROWTYPE;
BEGIN
    IF NEW.activo THEN
        SELECT * INTO v_convenio FROM convenio WHERE id_convenio = NEW.id_convenio AND activo;
        SELECT * INTO v_afectacion FROM afectacion WHERE id_afectacion = NEW.id_afectacion AND activo;
        IF v_convenio.id_convenio IS NULL OR v_afectacion.id_afectacion IS NULL
           OR v_convenio.id_proyecto_nucleo <> v_afectacion.id_proyecto_nucleo
           OR v_convenio.ambito <> v_afectacion.tipo_afectacion THEN
            RAISE EXCEPTION 'Convenio y afectación deben estar activos y compartir ProyectoNucleo/ámbito';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_convenio_individual_firmado()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id_convenio INTEGER;
    v_ambito VARCHAR(20);
    v_fecha_firma DATE;
    v_activo BOOLEAN;
BEGIN
    IF TG_TABLE_NAME = 'convenio' THEN
        v_id_convenio := NEW.id_convenio;
        IF TG_OP = 'UPDATE'
           AND OLD.fecha_firma IS NOT DISTINCT FROM NEW.fecha_firma
           AND OLD.ambito IS NOT DISTINCT FROM NEW.ambito
           AND OLD.activo IS NOT DISTINCT FROM NEW.activo THEN
            RETURN NULL;
        END IF;
    ELSE
        v_id_convenio := NEW.id_convenio;
    END IF;

    SELECT ambito, fecha_firma, activo
      INTO v_ambito, v_fecha_firma, v_activo
      FROM convenio
     WHERE id_convenio = v_id_convenio;

    IF NOT COALESCE(v_activo,FALSE)
       OR v_ambito IS DISTINCT FROM 'individual'
       OR v_fecha_firma IS NULL THEN
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM convenio_afectacion ca
          JOIN afectacion a ON a.id_afectacion = ca.id_afectacion
         WHERE ca.id_convenio = v_id_convenio
           AND ca.activo
           AND a.activo
           AND a.tipo_afectacion = 'individual'
    ) THEN
        RAISE EXCEPTION '039: convenio individual firmado requiere al menos una afectacion individual activa';
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM convenio_compareciente cc
         WHERE cc.id_convenio = v_id_convenio
           AND cc.activo
           AND cc.es_firmante
    ) THEN
        RAISE EXCEPTION '039: convenio individual firmado requiere al menos un firmante acreditado';
    END IF;

    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_convenio_relaciones()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_padre convenio%ROWTYPE; v_asamblea asamblea%ROWTYPE; v_contexto text;
BEGIN
    IF NEW.id_convenio_padre IS NOT NULL THEN
        IF NEW.id_convenio IS NOT NULL AND NEW.id_convenio_padre=NEW.id_convenio THEN
            RAISE EXCEPTION '007: un convenio no puede ser su propio padre';
        END IF;
        SELECT * INTO v_padre FROM convenio
         WHERE id_convenio=NEW.id_convenio_padre AND activo;
        IF NOT FOUND
           OR v_padre.id_proyecto_nucleo IS DISTINCT FROM NEW.id_proyecto_nucleo
           OR v_padre.ambito IS DISTINCT FROM NEW.ambito
           OR v_padre.tipo_instrumento IS DISTINCT FROM 'convenio' THEN
            RAISE EXCEPTION '007: el padre debe ser convenio activo del mismo ProyectoNucleo y ambito';
        END IF;
        IF NEW.tipo_convenio='cop_original'
           OR (NEW.tipo_convenio='obras_complementarias' AND v_padre.tipo_convenio NOT IN ('cop_original','obras_complementarias'))
           OR (NEW.tipo_convenio IN ('ampliacion','ampliacion_remanente') AND v_padre.tipo_convenio NOT IN ('cop_original','ampliacion')) THEN
            RAISE EXCEPTION '007: relacion padre/hijo no permitida para los tipos de convenio';
        END IF;
        IF NEW.id_convenio IS NOT NULL AND EXISTS (
            WITH RECURSIVE ancestro AS (
                SELECT c.id_convenio,c.id_convenio_padre FROM convenio c
                 WHERE c.id_convenio=NEW.id_convenio_padre
                UNION
                SELECT c.id_convenio,c.id_convenio_padre FROM convenio c
                JOIN ancestro a ON c.id_convenio=a.id_convenio_padre
                WHERE a.id_convenio_padre IS NOT NULL
            ) SELECT 1 FROM ancestro WHERE id_convenio=NEW.id_convenio
        ) THEN RAISE EXCEPTION '007: la relacion de convenios produciria un ciclo'; END IF;
    END IF;
    IF NEW.id_asamblea_autorizacion IS NOT NULL THEN
        SELECT * INTO v_asamblea FROM asamblea
         WHERE id_asamblea=NEW.id_asamblea_autorizacion AND activo;
        IF NEW.ambito IS DISTINCT FROM 'colectivo' OR v_asamblea.id_asamblea IS NULL
           OR v_asamblea.id_proyecto_nucleo IS DISTINCT FROM NEW.id_proyecto_nucleo THEN
            RAISE EXCEPTION '007: la Asamblea solo autoriza convenios colectivos del mismo ProyectoNucleo';
        END IF;
        SELECT c.codigo INTO v_contexto FROM catalogo_operativo c
         WHERE c.id_catalogo_opcion=v_asamblea.id_contexto_asamblea;
        IF v_contexto IS NOT NULL AND v_contexto<>'otro'
           AND v_contexto IS DISTINCT FROM NEW.tipo_convenio THEN
            RAISE EXCEPTION '007: el contexto de la Asamblea no corresponde al tipo de convenio';
        END IF;
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_documento_vinculo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.activo AND NOT fn_objetivo_controlado_existe(NEW.entidad_tipo, NEW.entidad_id) THEN
        RAISE EXCEPTION 'El objetivo documental %:% no existe', NEW.entidad_tipo, NEW.entidad_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_estado_antecedente_007()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    es_derivado boolean := NEW.tipo_instrumento = 'convenio'
        AND NEW.tipo_convenio IN ('modificatorio','obras_complementarias','ampliacion','ampliacion_remanente');
BEGIN
    IF NOT NEW.activo THEN RETURN NEW; END IF;
    IF NEW.estado_antecedente IS NULL
       OR (TG_OP='UPDATE'
           AND NEW.estado_antecedente IS NOT DISTINCT FROM OLD.estado_antecedente
           AND (NEW.tipo_instrumento IS DISTINCT FROM OLD.tipo_instrumento
                OR NEW.tipo_convenio IS DISTINCT FROM OLD.tipo_convenio
                OR NEW.id_convenio_padre IS DISTINCT FROM OLD.id_convenio_padre)) THEN
        NEW.estado_antecedente := CASE
            WHEN NEW.tipo_instrumento='convenio'
             AND NEW.tipo_convenio IN ('modificatorio','obras_complementarias','ampliacion','ampliacion_remanente')
             AND NEW.id_convenio_padre IS NOT NULL THEN 'vinculado'
            WHEN NEW.tipo_instrumento='convenio'
             AND NEW.tipo_convenio IN ('modificatorio','obras_complementarias','ampliacion','ampliacion_remanente')
                THEN 'pendiente_identificar'
            ELSE 'no_aplica'
        END;
    END IF;
    IF NEW.tipo_instrumento = 'convenio' AND NEW.tipo_convenio = 'cop_original' THEN
        IF NEW.id_convenio_padre IS NOT NULL OR NEW.estado_antecedente <> 'no_aplica' THEN
            RAISE EXCEPTION '007: COP original no admite padre ni estado de antecedente derivado';
        END IF;
    ELSIF es_derivado THEN
        IF NEW.id_convenio_padre IS NOT NULL AND NEW.estado_antecedente <> 'vinculado' THEN
            RAISE EXCEPTION '007: instrumento con padre debe declarar antecedente vinculado';
        END IF;
        IF NEW.id_convenio_padre IS NULL
           AND NEW.estado_antecedente NOT IN ('referido_sin_soporte','pendiente_identificar') THEN
            RAISE EXCEPTION '007: instrumento sin padre requiere antecedente referido o pendiente de identificar';
        END IF;
    ELSIF NEW.id_convenio_padre IS NOT NULL OR NEW.estado_antecedente <> 'no_aplica' THEN
        RAISE EXCEPTION '007: el instrumento no derivado no admite antecedente';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_expediente_requisito_objetivo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT fn_objetivo_requisito_en_pn(
        NEW.entidad_tipo, NEW.entidad_id, NEW.id_proyecto_nucleo
    ) THEN
        RAISE EXCEPTION 'Objetivo documental %:% no pertenece al ProyectoNucleo %',
            NEW.entidad_tipo, NEW.entidad_id, NEW.id_proyecto_nucleo;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_fifonafe_afectacion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_tramite tramite_fifonafe%ROWTYPE;
    v_afectacion afectacion%ROWTYPE;
BEGIN
    IF NEW.activo THEN
        SELECT * INTO v_tramite FROM tramite_fifonafe WHERE id_tramite_fifonafe = NEW.id_tramite_fifonafe AND activo;
        SELECT * INTO v_afectacion FROM afectacion WHERE id_afectacion = NEW.id_afectacion AND activo;
        IF v_tramite.id_tramite_fifonafe IS NULL OR v_afectacion.id_afectacion IS NULL
           OR v_tramite.id_proyecto_nucleo <> v_afectacion.id_proyecto_nucleo
           OR v_tramite.ambito <> v_afectacion.tipo_afectacion THEN
            RAISE EXCEPTION 'FIFONAFE y afectación deben estar activos y compartir ProyectoNucleo/ámbito';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_fifonafe_evento_v2_008()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_codigo text; v_version smallint; v_pn integer;
BEGIN
 SELECT c.codigo,t.version_flujo,t.id_proyecto_nucleo INTO v_codigo,v_version,v_pn
 FROM catalogo_operativo c CROSS JOIN tramite_fifonafe t
 WHERE c.id_catalogo_opcion=NEW.id_tipo_evento AND c.tipo_catalogo='tipo_evento_fifonafe'
   AND t.id_tramite_fifonafe=NEW.id_tramite_fifonafe;
 IF v_codigo IS NULL THEN RAISE EXCEPTION 'Tipo de evento FIFONAFE inválido'; END IF;
 IF v_version=1 AND v_codigo IN (
   'solicitud_retiro_colectivo','consulta_conflictos_enviada',
   'respuesta_conflictos_acreditada','resolucion_retiro_autorizada',
   'cancelacion_retiro','diferimiento_retiro','entrega_recursos',
   'comprobacion_entrega','requerimiento_judicial','cumplimiento_judicial',
   'dispensa_consulta_acreditada'
 ) THEN RAISE EXCEPTION 'Un trámite legado no adopta eventos v2 sin migración explícita autorizada'; END IF;
 IF NEW.id_documento IS NOT NULL AND NOT EXISTS (
   SELECT 1 FROM documento d JOIN documento_vinculo dv USING(id_documento)
   WHERE d.id_documento=NEW.id_documento AND d.activo AND dv.activo
     AND fn_objetivo_requisito_en_pn(dv.entidad_tipo,dv.entidad_id,v_pn)
 ) THEN RAISE EXCEPTION 'Documento FIFONAFE inexistente, inactivo o ajeno al ProyectoNucleo'; END IF;
 IF NEW.conflicto_impide_retiro IS NOT NULL
    AND v_codigo NOT IN ('respuesta_conflictos_acreditada','respuesta_dgaopr_fifonafe') THEN
   RAISE EXCEPTION 'El impedimento sólo corresponde a una respuesta de conflictos';
 END IF;
 IF v_version=2 AND v_codigo='respuesta_conflictos_acreditada' AND
    (NEW.ciclo_consulta IS NULL OR coalesce(NEW.fecha_evento,NEW.fecha_oficio) IS NULL
     OR NEW.conflicto_impide_retiro IS NULL) THEN
   RAISE EXCEPTION 'Respuesta acreditada v2 requiere ronda, fecha y alcance del impedimento';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_fifonafe_interviniente_008()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_fecha date;
BEGIN
  IF TG_OP='UPDATE' AND (OLD.id_tramite_fifonafe,OLD.id_persona,OLD.rol,OLD.id_evento_fifonafe)
       IS DISTINCT FROM (NEW.id_tramite_fifonafe,NEW.id_persona,NEW.rol,NEW.id_evento_fifonafe) THEN
    RAISE EXCEPTION 'Identidad del interviniente inmutable; use baja lógica y alta nueva';
  END IF;
  IF NEW.activo AND NOT EXISTS (SELECT 1 FROM persona WHERE id_persona=NEW.id_persona AND activo) THEN
    RAISE EXCEPTION 'Persona inexistente o inactiva';
  END IF;
  IF NEW.id_evento_fifonafe IS NOT NULL THEN
    SELECT coalesce(e.fecha_evento,e.fecha_oficio) INTO v_fecha
    FROM tramite_fifonafe_evento e
    WHERE e.id_evento_fifonafe=NEW.id_evento_fifonafe AND e.activo
      AND e.id_tramite_fifonafe=NEW.id_tramite_fifonafe;
    IF NOT FOUND THEN RAISE EXCEPTION 'Evento ajeno o inactivo'; END IF;
  END IF;
  IF NEW.id_orv_integrante IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM orv_integrante oi JOIN orv o ON o.id_orv=oi.id_orv
    JOIN proyecto_nucleo pn ON pn.id_nucleo=o.id_nucleo
    WHERE oi.id_orv_integrante=NEW.id_orv_integrante AND oi.activo AND o.activo
      AND oi.id_persona=NEW.id_persona
      AND pn.id_proyecto_nucleo=(SELECT id_proyecto_nucleo FROM tramite_fifonafe
                                 WHERE id_tramite_fifonafe=NEW.id_tramite_fifonafe)
      AND (v_fecha IS NULL OR ((oi.fecha_inicio IS NULL OR oi.fecha_inicio<=v_fecha)
            AND (oi.fecha_fin IS NULL OR oi.fecha_fin>=v_fecha)))
  ) THEN RAISE EXCEPTION 'Integrante ORV no acredita persona, nucleo o vigencia a la fecha del acto'; END IF;
  IF NEW.id_orv_integrante IS NOT NULL AND
     (NEW.id_evento_fifonafe IS NULL OR v_fecha IS NULL) THEN
    RAISE EXCEPTION 'La representación ORV histórica requiere un acto FIFONAFE con fecha de negocio';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_importacion_celda()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.entidad_id IS NOT NULL AND NOT fn_objetivo_controlado_existe(NEW.entidad_tipo,NEW.entidad_id) THEN
        RAISE EXCEPTION 'Objetivo de celda importada %:% no existe',NEW.entidad_tipo,NEW.entidad_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_importacion_feature_objetivo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_objetivo varchar(30);
    v_id_proyecto integer;
    v_tipo text;
    v_destino_existe boolean;
BEGIN
    SELECT tipo_objetivo, id_proyecto INTO v_objetivo, v_id_proyecto
      FROM importacion_archivo
     WHERE id_importacion = NEW.id_importacion AND activo;
    IF v_objetivo IS NULL THEN
        RAISE EXCEPTION 'La importación padre no existe o está inactiva';
    END IF;

    IF (SELECT version_pipeline FROM importacion_archivo WHERE id_importacion=NEW.id_importacion) <> 'legacy-v1' THEN
        IF NEW.geometria_trabajo IS NOT NULL AND ST_SRID(NEW.geometria_trabajo)<>
           (SELECT srid_trabajo FROM importacion_archivo WHERE id_importacion=NEW.id_importacion) THEN
            RAISE EXCEPTION 'CRS de staging distinto del CRS de importacion';
        END IF;
        IF NEW.registro_destino_id IS NOT NULL AND v_objetivo IN('nucleo_agrario','nucleo_agrario_gpkg','parcela','parcela_gpkg')
           AND NOT EXISTS(SELECT 1 FROM importacion_feature_candidato c
             WHERE c.id_importacion_feature=NEW.id_importacion_feature AND c.estado='confirmado'
             AND CASE WHEN c.id_parcela IS NULL THEN c.id_proyecto_nucleo ELSE c.id_parcela END=NEW.registro_destino_id) THEN
            RAISE EXCEPTION 'Destino sin candidato confirmado';
        END IF;
        IF NEW.geometria_normalizada IS NOT NULL AND GeometryType(NEW.geometria_normalizada)<>'MULTIPOLYGON' THEN
            RAISE EXCEPTION 'Contrato poligonal de conciliacion';
        END IF;
        IF NEW.estado='confirmado' AND (NEW.registro_destino_id IS NULL
           OR NEW.geometria_normalizada IS NULL OR NEW.geometria_trabajo IS NULL
           OR jsonb_array_length(NEW.errores)>0
           OR (jsonb_array_length(NEW.advertencias)>0 AND NOT NEW.advertencias_aceptadas)) THEN
            RAISE EXCEPTION 'Feature confirmada sin geometria o decision valida';
        END IF;
        IF v_objetivo IN('nucleo_agrario','nucleo_agrario_gpkg','parcela','parcela_gpkg') THEN
            RETURN NEW;
        END IF;
    END IF;

    IF NEW.geometria_normalizada IS NOT NULL THEN
        v_tipo := GeometryType(NEW.geometria_normalizada);
        IF (v_objetivo = 'trazo_proyecto' AND v_tipo <> 'MULTILINESTRING')
           OR (v_objetivo IN ('nucleo_agrario', 'parcela',
                             'derecho_via_proyecto', 'nucleo_agrario_gpkg',
                             'parcela_gpkg') AND v_tipo <> 'MULTIPOLYGON') THEN
            RAISE EXCEPTION 'Tipo geométrico % inválido para objetivo %',
                v_tipo, v_objetivo;
        END IF;
    END IF;

    IF NEW.registro_destino_id IS NOT NULL THEN
        IF v_objetivo = 'trazo_proyecto' THEN
            SELECT EXISTS (
                SELECT 1 FROM trazo_proyecto
                 WHERE id_trazo = NEW.registro_destino_id
            ) INTO v_destino_existe;
        ELSIF v_objetivo = 'nucleo_agrario' THEN
            SELECT EXISTS (
                SELECT 1 FROM nucleo_agrario
                 WHERE id_nucleo = NEW.registro_destino_id
            ) INTO v_destino_existe;
        ELSIF v_objetivo = 'nucleo_agrario_gpkg' THEN
            SELECT EXISTS (
                SELECT 1 FROM nucleo_agrario n
                JOIN proyecto_nucleo pn ON pn.id_nucleo = n.id_nucleo
                 WHERE n.id_nucleo = NEW.registro_destino_id
                   AND n.activo AND pn.activo AND pn.id_proyecto = v_id_proyecto
                   AND lower(btrim(n.fuente_datos)) = 'ran_phina_catalogo_nucleos'
                   AND btrim(n.id_nucleo_fuente) = NEW.atributos_normalizados->>'cve_unica'
            ) INTO v_destino_existe;
        ELSIF v_objetivo = 'parcela_gpkg' THEN
            SELECT EXISTS (
                SELECT 1 FROM parcela p
                JOIN nucleo_agrario n ON n.id_nucleo = p.id_nucleo
                JOIN proyecto_nucleo pn ON pn.id_nucleo = n.id_nucleo
                 WHERE p.id_parcela = NEW.registro_destino_id
                   AND p.activo AND n.activo AND pn.activo
                   AND pn.id_proyecto = v_id_proyecto
                   AND lower(btrim(n.fuente_datos)) = 'ran_phina_catalogo_nucleos'
                   AND btrim(n.id_nucleo_fuente) =
                       NEW.atributos_normalizados->>'cve_unica_nucleo'
                   AND p.id_nucleo =
                       (NEW.atributos_normalizados->>'id_nucleo')::integer
            ) INTO v_destino_existe;
        ELSIF v_objetivo = 'parcela' THEN
            SELECT EXISTS (
                SELECT 1 FROM parcela
                 WHERE id_parcela = NEW.registro_destino_id
            ) INTO v_destino_existe;
        ELSE
            SELECT EXISTS (
                SELECT 1 FROM derecho_via_proyecto
                 WHERE id_derecho_via = NEW.registro_destino_id
                   AND id_proyecto = v_id_proyecto
            ) INTO v_destino_existe;
        END IF;
        IF NOT v_destino_existe THEN
            RAISE EXCEPTION
                'El registro destino confirmado no existe para el objetivo %',
                v_objetivo;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_linaje_convenio_individual()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_padre convenio%ROWTYPE; v_cycle boolean := false;
BEGIN
    IF NOT NEW.activo OR NEW.ambito IS DISTINCT FROM 'individual' THEN RETURN NEW; END IF;
    IF NEW.id_asamblea_autorizacion IS NOT NULL THEN
        RAISE EXCEPTION '039: convenio individual no debe usar Asamblea como autorizacion';
    END IF;
    IF NEW.tipo_instrumento = 'convenio' THEN
        IF NEW.tipo_convenio NOT IN ('cop_original','modificatorio','ampliacion','ampliacion_remanente') THEN
            RAISE EXCEPTION '039: tipo de convenio % no corresponde al flujo individual', NEW.tipo_convenio;
        END IF;
        IF NEW.tipo_convenio = 'cop_original' AND NEW.id_convenio_padre IS NOT NULL THEN
            RAISE EXCEPTION '039: cop_original individual no debe tener convenio padre';
        END IF;
        IF NEW.id_convenio_padre IS NOT NULL THEN
            IF NEW.id_convenio IS NOT NULL AND NEW.id_convenio_padre = NEW.id_convenio THEN
                RAISE EXCEPTION '039: un convenio no puede ser su propio padre';
            END IF;
            SELECT * INTO v_padre FROM convenio
             WHERE id_convenio=NEW.id_convenio_padre AND activo;
            IF NOT FOUND THEN RAISE EXCEPTION '039: convenio padre inexistente o inactivo'; END IF;
            IF v_padre.id_proyecto_nucleo IS DISTINCT FROM NEW.id_proyecto_nucleo
               OR v_padre.ambito IS DISTINCT FROM 'individual'
               OR v_padre.tipo_instrumento IS DISTINCT FROM 'convenio' THEN
                RAISE EXCEPTION '039: convenio padre debe compartir ProyectoNucleo, ambito individual y ser un convenio';
            END IF;
            IF NEW.id_convenio IS NOT NULL THEN
                WITH RECURSIVE ancestros AS (
                    SELECT c.id_convenio,c.id_convenio_padre FROM convenio c WHERE c.id_convenio=NEW.id_convenio_padre
                    UNION ALL
                    SELECT p.id_convenio,p.id_convenio_padre FROM convenio p
                    JOIN ancestros a ON p.id_convenio=a.id_convenio_padre
                    WHERE p.id_convenio_padre IS NOT NULL
                ) SELECT EXISTS(SELECT 1 FROM ancestros WHERE id_convenio=NEW.id_convenio) INTO v_cycle;
                IF v_cycle THEN RAISE EXCEPTION '039: el linaje de convenio no puede contener ciclos'; END IF;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_linaje_unidad_individual()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id_convenio INTEGER;
    v_padre INTEGER;
    v_ambito VARCHAR(20);
    v_activo BOOLEAN;
BEGIN
    v_id_convenio := NEW.id_convenio;

    SELECT id_convenio_padre, ambito, activo
      INTO v_padre, v_ambito, v_activo
      FROM convenio
     WHERE id_convenio = v_id_convenio;

    IF NOT COALESCE(v_activo,FALSE)
       OR v_ambito IS DISTINCT FROM 'individual'
       OR v_padre IS NULL THEN
        RETURN NULL;
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM convenio_afectacion ca_hijo
          JOIN afectacion_unidad_agraria au_hijo
            ON au_hijo.id_afectacion = ca_hijo.id_afectacion
           AND au_hijo.activo
          JOIN convenio_afectacion ca_padre
            ON ca_padre.id_convenio = v_padre
           AND ca_padre.activo
          JOIN afectacion_unidad_agraria au_padre
            ON au_padre.id_afectacion = ca_padre.id_afectacion
           AND au_padre.id_unidad_agraria = au_hijo.id_unidad_agraria
           AND au_padre.activo
         WHERE ca_hijo.id_convenio = v_id_convenio
           AND ca_hijo.activo
    ) THEN
        RAISE EXCEPTION '039: convenio individual hijo debe compartir al menos una UnidadAgraria con su convenio padre';
    END IF;

    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_orv_integrante_finalizacion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_codigo text;
BEGIN
    IF NEW.id_tipo_fin IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT codigo INTO v_codigo
      FROM catalogo_operativo
     WHERE id_catalogo_opcion = NEW.id_tipo_fin
       AND tipo_catalogo = 'tipo_fin_orv_integrante'
       AND activo;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tipo de finalizacion ORV invalido';
    END IF;
    IF v_codigo = 'otro' AND NULLIF(btrim(NEW.detalle_fin), '') IS NULL THEN
        RAISE EXCEPTION 'El tipo de finalizacion otro requiere detalle';
    END IF;
    IF v_codigo = 'sin_clasificar'
       AND (TG_OP = 'INSERT' OR OLD.id_tipo_fin IS DISTINCT FROM NEW.id_tipo_fin) THEN
        RAISE EXCEPTION 'sin_clasificar se reserva para datos historicos migrados';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_persona_relacion_activa()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id_persona integer;
BEGIN
    IF NOT NEW.activo THEN
        RETURN NEW;
    END IF;
    v_id_persona := NULLIF(to_jsonb(NEW) ->> TG_ARGV[0], '')::integer;
    IF v_id_persona IS NULL THEN
        RETURN NEW;
    END IF;
    PERFORM pg_advisory_xact_lock(
        hashtextextended('software-pa:persona-relaciones:' || v_id_persona, 0)
    );
    IF NOT EXISTS (
        SELECT 1 FROM persona WHERE id_persona = v_id_persona AND activo
    ) THEN
        RAISE EXCEPTION 'Persona inexistente o inactiva';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_pn_tuc()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_codigo TEXT;
BEGIN
    IF NOT fn_opcion_catalogo_valida(NEW.id_motivo_no_afecta_tuc,'motivo_no_afecta_tuc') THEN
        RAISE EXCEPTION 'Motivo de no afectacion TUC invalido';
    END IF;

    IF NEW.afecta_tuc IS FALSE THEN
        SELECT codigo INTO v_codigo
        FROM catalogo_operativo
        WHERE id_catalogo_opcion=NEW.id_motivo_no_afecta_tuc;
        IF v_codigo='otro' AND NULLIF(btrim(NEW.motivo_no_afecta_tuc_detalle),'') IS NULL THEN
            RAISE EXCEPTION 'El motivo otro requiere detalle';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_seguimiento_evento()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_tipo text; v_motivo text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.id_proyecto_nucleo <> OLD.id_proyecto_nucleo THEN
            RAISE EXCEPTION 'No se permite cambiar el ProyectoNucleo de un evento de seguimiento';
        END IF;
        IF NEW.ambito <> OLD.ambito THEN
            RAISE EXCEPTION 'No se permite cambiar el ámbito de un evento de seguimiento';
        END IF;
        IF NEW.id_tipo_evento <> OLD.id_tipo_evento THEN
            RAISE EXCEPTION 'No se permite reescribir el tipo de evento; la transición debe registrarse mediante un nuevo evento';
        END IF;
        IF NEW.id_motivo IS DISTINCT FROM OLD.id_motivo THEN
            RAISE EXCEPTION 'No se permite cambiar el motivo de un evento de seguimiento';
        END IF;
        IF (NEW.entidad_tipo IS DISTINCT FROM OLD.entidad_tipo) OR (NEW.entidad_id IS DISTINCT FROM OLD.entidad_id) THEN
            RAISE EXCEPTION 'No se permite cambiar el objetivo de un evento de seguimiento';
        END IF;
    END IF;

    IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_evento,'tipo_evento_seguimiento') THEN
        RAISE EXCEPTION 'Tipo de evento de seguimiento inválido';
    END IF;
    IF NEW.id_motivo IS NOT NULL AND NOT fn_opcion_catalogo_valida(NEW.id_motivo,'motivo_seguimiento') THEN
        RAISE EXCEPTION 'Motivo de seguimiento inválido';
    END IF;
    IF NEW.entidad_tipo IS NOT NULL
       AND NOT fn_objetivo_seguimiento_en_pn(NEW.entidad_tipo,NEW.entidad_id,NEW.id_proyecto_nucleo) THEN
        RAISE EXCEPTION 'El objetivo de seguimiento no existe, está inactivo o no pertenece al ProyectoNucleo';
    END IF;
    SELECT codigo INTO v_tipo FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_tipo_evento;
    SELECT codigo INTO v_motivo FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_motivo;
    IF v_tipo='suspension' AND NEW.id_motivo IS NULL THEN
        RAISE EXCEPTION 'La suspensión requiere motivo';
    END IF;
    IF v_tipo='reapertura' AND NULLIF(btrim(NEW.detalle),'') IS NULL THEN
        RAISE EXCEPTION 'La reapertura requiere detalle';
    END IF;
    IF v_tipo IN ('cierre','cambio_alcance') AND (NEW.id_motivo IS NULL OR NULLIF(btrim(NEW.detalle),'') IS NULL) THEN
        RAISE EXCEPTION '% requiere motivo y detalle', v_tipo;
    END IF;
    IF v_motivo='otro' AND NULLIF(btrim(NEW.detalle),'') IS NULL THEN
        RAISE EXCEPTION 'El motivo otro requiere detalle';
    END IF;
    IF v_tipo='continuacion_asamblea' AND NEW.entidad_tipo NOT IN ('asamblea','asamblea_convocatoria') THEN
        RAISE EXCEPTION 'La continuación de asamblea requiere objetivo asamblea o convocatoria';
    END IF;
    IF v_motivo='dominio_pleno' AND (NEW.ambito <> 'individual' OR NEW.entidad_tipo NOT IN ('parcela','afectacion','unidad_agraria')) THEN
        RAISE EXCEPTION 'Dominio pleno sólo admite ámbito individual y objetivo parcela, afectación o unidad agraria';
    END IF;
    IF v_motivo IN ('conflicto_titularidad','juicio_agrario') AND (NEW.ambito <> 'individual' OR NEW.entidad_tipo NOT IN ('parcela','parcela_titular','afectacion','unidad_agraria')) THEN
        RAISE EXCEPTION 'Conflicto de titularidad o juicio agrario sólo admite objetivo individual compatible';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_seguimiento_post_auditoria()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE tipo text;
BEGIN
 SELECT codigo INTO tipo FROM catalogo_operativo WHERE id_catalogo_opcion=NEW.id_tipo_evento;
 IF tipo IN ('inicio','suspension','reapertura','cierre','cambio_alcance') AND NEW.fecha_evento IS NULL THEN RAISE EXCEPTION 'El evento de transición % requiere fecha_evento',tipo; END IF;
 IF NEW.id_documento IS NOT NULL AND NOT EXISTS (SELECT 1 FROM documento d JOIN documento_vinculo dv ON dv.id_documento=d.id_documento AND dv.activo WHERE d.id_documento=NEW.id_documento AND d.activo AND fn_objetivo_requisito_en_pn(dv.entidad_tipo,dv.entidad_id,NEW.id_proyecto_nucleo)) THEN RAISE EXCEPTION 'Documento inexistente, inactivo o ajeno al ProyectoNucleo del seguimiento'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_validar_tramite_ran_contexto()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_pn INTEGER; v_nucleo INTEGER;
BEGIN
  IF NOT NEW.activo THEN RETURN NEW; END IF;
  IF NEW.id_asamblea IS NOT NULL THEN
    SELECT id_proyecto_nucleo INTO v_pn FROM asamblea
    WHERE id_asamblea=NEW.id_asamblea AND activo;
    IF v_pn IS NULL OR NEW.id_proyecto_nucleo IS DISTINCT FROM v_pn OR NEW.id_nucleo IS NOT NULL THEN
      RAISE EXCEPTION 'TramiteRAN de Asamblea debe usar su ProyectoNucleo';
    END IF;
  ELSIF NEW.id_convenio IS NOT NULL THEN
    SELECT id_proyecto_nucleo INTO v_pn FROM convenio
    WHERE id_convenio=NEW.id_convenio AND activo;
    IF v_pn IS NULL OR NEW.id_proyecto_nucleo IS DISTINCT FROM v_pn OR NEW.id_nucleo IS NOT NULL THEN
      RAISE EXCEPTION 'TramiteRAN de Convenio debe usar su ProyectoNucleo';
    END IF;
  ELSIF NEW.id_orv IS NOT NULL THEN
    SELECT id_nucleo INTO v_nucleo FROM orv WHERE id_orv=NEW.id_orv AND activo;
    IF v_nucleo IS NULL OR NEW.id_nucleo IS DISTINCT FROM v_nucleo OR NEW.id_proyecto_nucleo IS NOT NULL THEN
      RAISE EXCEPTION 'TramiteRAN de ORV debe usar su NucleoAgrario';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_trazabilidad_objetivo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NOT fn_objetivo_controlado_existe(NEW.entidad_tipo, NEW.entidad_id) THEN
        RAISE EXCEPTION 'El objetivo de trazabilidad %:% no existe o no está permitido', NEW.entidad_tipo, NEW.entidad_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_unidad_agraria()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_nucleo_parcela INTEGER;
BEGIN
    IF NOT fn_opcion_catalogo_valida(NEW.id_tipo_tierra,'tipo_tierra')
       OR NOT fn_opcion_catalogo_valida(NEW.id_tipo_gestion,'tipo_gestion')
       OR NOT fn_opcion_catalogo_valida(NEW.id_destino_superficie,'destino_superficie')
       OR NOT fn_opcion_catalogo_valida(NEW.id_tipo_titularidad,'tipo_titularidad_unidad') THEN
        RAISE EXCEPTION 'La unidad agraria contiene catalogos de tipo incorrecto';
    END IF;

    NEW.referencia_normalizada := fn_normalizar_referencia(NEW.referencia_alfanumerica);

    IF NEW.id_parcela IS NOT NULL AND NEW.activo THEN
        SELECT id_nucleo INTO v_nucleo_parcela
        FROM parcela
        WHERE id_parcela=NEW.id_parcela AND activo;
        IF v_nucleo_parcela IS NULL OR v_nucleo_parcela<>NEW.id_nucleo THEN
            RAISE EXCEPTION 'La parcela de la unidad agraria debe pertenecer al mismo nucleo';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_validar_unidad_titular()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_nucleo_unidad INTEGER;
    v_nucleo_parcela INTEGER;
    v_persona_parcela INTEGER;
    v_persona_directa INTEGER;
    v_tipo_titularidad TEXT;
BEGIN
    SELECT u.id_nucleo, c.codigo
      INTO v_nucleo_unidad, v_tipo_titularidad
    FROM unidad_agraria u
    JOIN catalogo_operativo c ON c.id_catalogo_opcion=u.id_tipo_titularidad
    WHERE u.id_unidad_agraria=NEW.id_unidad_agraria AND u.activo;

    IF v_nucleo_unidad IS NULL THEN
        RAISE EXCEPTION 'La unidad agraria titular debe estar activa';
    END IF;
    IF v_tipo_titularidad NOT IN ('persona','copropiedad') THEN
        RAISE EXCEPTION 'Solo unidades con titularidad persona/copropiedad admiten titulares persona';
    END IF;

    IF NEW.id_parcela_titular IS NOT NULL THEN
        SELECT p.id_nucleo, pt.id_persona
          INTO v_nucleo_parcela, v_persona_parcela
        FROM parcela_titular pt
        JOIN parcela p ON p.id_parcela=pt.id_parcela
        WHERE pt.id_parcela_titular=NEW.id_parcela_titular
          AND pt.activo AND p.activo;
        IF v_nucleo_parcela IS NULL OR v_nucleo_parcela<>v_nucleo_unidad THEN
            RAISE EXCEPTION 'ParcelaTitular debe pertenecer al mismo nucleo de la unidad agraria';
        END IF;
    ELSE
        SELECT id_persona INTO v_persona_directa
        FROM persona WHERE id_persona=NEW.id_persona AND activo;
        IF v_persona_directa IS NULL THEN
            RAISE EXCEPTION 'La persona titular debe estar activa';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
